import{_ as e,o as i,c as a,e as o}from"./app-6be1f847.js";const l={},t=o('<h2 id="chapter4-非谓语动词" tabindex="-1"><a class="header-anchor" href="#chapter4-非谓语动词" aria-hidden="true">#</a> chapter4 非谓语动词</h2><h3 id="不定时的-3-种功能" tabindex="-1"><a class="header-anchor" href="#不定时的-3-种功能" aria-hidden="true">#</a> 不定时的 3 种功能</h3><ul><li>作名词：to take a trip around the world has been my dream.</li><li>adjective: i have something to do.</li><li>副词：i came to see her.</li></ul><h4 id="名词不定时" tabindex="-1"><a class="header-anchor" href="#名词不定时" aria-hidden="true">#</a> 名词不定时</h4><p>名词可在句子中做 主语、宾语、表语，同理名词不定时也可以做这三种成分。</p><ul><li>做主语：表示一种意愿或未完成的事 （to marry her is my dream） <ul><li>名词不定式做主语时，be动词之后的表语若为名词，一定为表意愿、目的、企图等名词，以表示意愿或尚未完成的事。常用的此类名词为 plan/purpose/attempt/goal/aim/ambition/dream/ideal理想/wish/hope/decision/determination/proposal建议。</li><li>名词不定式做主语一般使用it做形式主语</li></ul></li><li>名词不定式做及物动词的宾语时，该及物动词均为表意愿和企图的动词，常用的有：want/wish/hope/desire/intend/endeavor努力/like/love/expect</li><li>名词不定式不可直接做不完全及物动词的宾语，一定要以形式宾语 it 代替，加了宾语补足语之后，再接名词不定式（i find it interesting to climb mountains）。</li><li>名词不定式在 be 动词后做表语，此时主语均为表 意愿 企图 的名词。（his resolution志愿 is to be a scientist） <ul><li>动词不定式做表语特殊句型，be 动词之后的 to 可以省略，改接原型动词做表语</li><li><em>all you have to do</em> is <s>to</s> take a good rest</li><li><em>all i can do</em> is <s>to</s> wait</li><li><em>what you should do</em> is simply <s>to</s> apologize to him</li><li><em>all id did yesterday</em> was <s>to</s> eat and sleep</li></ul></li></ul><h4 id="形容词不定式" tabindex="-1"><a class="header-anchor" href="#形容词不定式" aria-hidden="true">#</a> 形容词不定式</h4><p>此类不定式一定采用后位修饰，也就是置于名词的后面，做形容词用，修饰其前面的名词</p><ul><li>形容词不定式也可等于关系代词做宾语所引导的定语从句,此类句型中被修饰的名词一定要做不定式短语中动词的宾语，否则就要做介词的宾语</li></ul><p>例1. i want sth to eat = i want sth which i can eat 例2. i have no one to talk to = i have no one whom i can talk to</p><ul><li>be 动词之后加形容词不定式有以下意义 <ul><li>主动形式：表将来=will (he is to come tomorrow);表义务(=should),you are to do it。</li><li>被动形式：表当然=should, <code>Such a lazy man is to be fired。</code>;表可能=can,<code>My hat was nowhere to be found</code>。</li></ul></li></ul><h4 id="副词不定式" tabindex="-1"><a class="header-anchor" href="#副词不定式" aria-hidden="true">#</a> 副词不定式</h4><p>该不定式可以修饰动词、形容词、副词。</p><ul><li>修饰动词，一定置于该动词之后，<code>He has agreed to do it</code> 。副词不定式修饰动词时，多半表示目的，此时该副词不定式亦同时修饰含该动词的整个句子。表目的的副词不定式，通常置于动词之后，但亦可以移位至主语之前，以逗号相隔（to please her,he sang a song。），此时，该不定式亦兼具形容词功能，修饰句中主语，该主语通常是表人的名词或代词，即该不定式所表示的动作，必须是它所修饰的主语的动作。</li><li>修饰形容词，一定置于该形容词之后，This book is good to read。</li><li>修饰副词，一定置于该副词之后，He is too old to swim(to swim 修饰 too)。</li></ul>',14),s=[t];function r(d,h){return i(),a("div",null,s)}const c=e(l,[["render",r],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/english/grammar.html.vue"]]);export{c as default};
